HERO_STR_STATIC(hero_str_1f12681, "-Wl,-rpath,");
HERO_STR_STATIC(hero_str_25c32dd1, "-Wl,-framework,");
HERO_STR_STATIC(hero_str_41cfb242, "`, which this compiler does not pass on\n  only `-D`, `-U`, `-I`, `-L`, `-l`, `-F`, `-framework`, `-Wl,-framework,<name>` and `-Wl,-rpath,<dir>` are accepted: everything else is a flag a package file could use to run code during the build (Go's CVE-2018-6574)\n  name the library directly with `link` if you need it");
HERO_STR_STATIC(hero_str_174b, "-D");
